Here’s a minimal Flask implementation with SQLite, password hashing, CSRF protection, login rate limits, and secure session cookies.

### 1. Install dependencies

```bash
pip install Flask Flask-WTF Flask-Limiter email-validator
```

### 2. Save as `app.py`

```python
import os
import sqlite3

from flask import Flask, flash, redirect, render_template_string, session, url_for
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from flask_wtf import FlaskForm
from werkzeug.security import check_password_hash, generate_password_hash
from wtforms import PasswordField, StringField, SubmitField
from wtforms.validators import DataRequired, Email, Length

app = Flask(__name__)

# Required: generate a long random value and keep it secret.
app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
# Set to "0" only for local development over HTTP.
app.config["SESSION_COOKIE_SECURE"] = os.getenv("COOKIE_SECURE", "1") == "1"

limiter = Limiter(
    key_func=get_remote_address,
    app=app,
    default_limits=[],
    storage_uri="memory://",
)

DB_PATH = os.getenv("DATABASE_PATH", "customers.db")


def connect_db():
    return sqlite3.connect(DB_PATH, timeout=10)


with connect_db() as db:
    db.execute("""
        CREATE TABLE IF NOT EXISTS customers (
            id INTEGER PRIMARY KEY,
            email TEXT NOT NULL UNIQUE,
            password_hash TEXT NOT NULL
        )
    """)


class AuthForm(FlaskForm):
    email = StringField(
        "Email",
        validators=[DataRequired(), Email(), Length(max=254)],
    )
    password = PasswordField(
        "Password",
        validators=[DataRequired(), Length(min=12, max=128)],
    )
    submit = SubmitField("Submit")


class LogoutForm(FlaskForm):
    submit = SubmitField("Log out")


PAGE = """
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>{{ title }}</title>
</head>
<body>
  <h1>{{ title }}</h1>

  {% for message in get_flashed_messages() %}
    <p>{{ message }}</p>
  {% endfor %}

  {% if form %}
    <form method="post">
      {{ form.hidden_tag() }}
      {% if form.email is defined %}
        <p>
          {{ form.email.label }}<br>
          {{ form.email(type="email", autocomplete="email") }}
          {% for error in form.email.errors %}<br>{{ error }}{% endfor %}
        </p>
        <p>
          {{ form.password.label }}<br>
          {{ form.password(autocomplete=password_autocomplete) }}
          {% for error in form.password.errors %}<br>{{ error }}{% endfor %}
        </p>
      {% endif %}
      {{ form.submit() }}
    </form>
  {% endif %}

  <p>
    <a href="{{ url_for('account') }}">Account</a> |
    <a href="{{ url_for('login') }}">Log in</a> |
    <a href="{{ url_for('register') }}">Register</a>
  </p>
</body>
</html>
"""


@app.route("/register", methods=["GET", "POST"])
@limiter.limit("5 per hour", methods=["POST"])
def register():
    form = AuthForm()
    if form.validate_on_submit():
        email = form.email.data.strip().lower()
        password_hash = generate_password_hash(form.password.data, method="scrypt")

        try:
            with connect_db() as db:
                db.execute(
                    "INSERT INTO customers (email, password_hash) VALUES (?, ?)",
                    (email, password_hash),
                )
        except sqlite3.IntegrityError:
            flash("An account with that email already exists.")
        else:
            flash("Account created. Please log in.")
            return redirect(url_for("login"))

    return render_template_string(
        PAGE, title="Register", form=form,
        password_autocomplete="new-password",
    )


@app.route("/login", methods=["GET", "POST"])
@limiter.limit("10 per minute", methods=["POST"])
def login():
    form = AuthForm()
    if form.validate_on_submit():
        email = form.email.data.strip().lower()
        with connect_db() as db:
            customer = db.execute(
                "SELECT id, password_hash FROM customers WHERE email = ?",
                (email,),
            ).fetchone()

        if customer and check_password_hash(customer[1], form.password.data):
            session.clear()
            session["customer_id"] = customer[0]
            return redirect(url_for("account"))

        flash("Invalid email or password.")

    return render_template_string(
        PAGE, title="Log in", form=form,
        password_autocomplete="current-password",
    )


@app.get("/account")
def account():
    customer_id = session.get("customer_id")
    if not customer_id:
        return redirect(url_for("login"))

    with connect_db() as db:
        customer = db.execute(
            "SELECT email FROM customers WHERE id = ?", (customer_id,)
        ).fetchone()

    if not customer:
        session.clear()
        return redirect(url_for("login"))

    flash(f"Signed in as {customer[0]}")
    return render_template_string(
        PAGE, title="Your account", form=LogoutForm(),
        password_autocomplete="",
    ).replace('method="post"', f'method="post" action="{url_for("logout")}"')


@app.post("/logout")
def logout():
    form = LogoutForm()
    if not form.validate_on_submit():
        return "Invalid request", 400
    session.clear()
    flash("You have logged out.")
    return redirect(url_for("login"))


if __name__ == "__main__":
    app.run()
```

### 3. Run locally

```bash
export SECRET_KEY="$(python -c 'import secrets; print(secrets.token_hex(32))')"
export COOKIE_SECURE=0
python app.py
```

Open `http://127.0.0.1:5000/register`. Keep the same `SECRET_KEY` across restarts or existing sessions will be invalidated.

**Before production:** serve the app over HTTPS with `COOKIE_SECURE=1` using a production WSGI server. Replace the in-memory rate-limit store with a shared store such as Redis, especially if running multiple workers. Add email verification, password reset, and appropriate customer-data and privacy controls for your shop.

